<h2>Convert frame rate and clip duration</h2><p class="lead">Calculate total frames, source duration and retimed playback duration when frame rate changes.</p><div class="notice">Use this for conforming footage or timelapse planning. It does not model frame blending, optical flow or drop-frame timecode conventions.</div><div class="form-grid"><div class="field"><label for="duration">Recorded duration (seconds)</label><input id="duration" type="number" value="10" min="0.001" step="any"></div><div class="field"><label for="src">Source frame rate (fps)</label><input id="src" type="number" value="60" min="0.001" step="any"></div><div class="field"><label for="dst">Playback / timeline frame rate (fps)</label><input id="dst" type="number" value="24" min="0.001" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Total frames</span><strong id="frames">—</strong></div><div class="metric"><span>Playback duration</span><strong id="play">—</strong></div><div class="metric"><span>Playback speed</span><strong id="speed">—</strong></div><div class="metric"><span>Duration multiplier</span><strong id="factor">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('frames').textContent='—';$('play').textContent='—';$('speed').textContent='—';$('factor').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const d=num('duration'),s=num('src'),p=num('dst');if(!(d>0&&s>0&&p>0))throw 0;const frames=d*s,play=frames/p,speed=p/s*100,m=play/d;$('frames').textContent=fmt(frames,0);$('play').textContent=fmt(play,3)+' s';$('speed').textContent=fmt(speed,2)+'%';$('factor').textContent=fmt(m,3)+'×';$('note').textContent='This assumes every recorded frame is conformed to the target frame rate without frame interpolation or dropping.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
